import time, random
def call_service(retries=3, delay=1.0):
    try:
        return requests.get(url)
    except Exception as e:
        if retries <= 0: raise e
        time.sleep(delay + random.uniform(0, delay))
        return call_service(retries - 1, delay * 2)

